// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address newRoundImplementation) public {
        // domain: full address space — the zero address is exactly the
        // admissible input that separates the reference from the mutant.
        address owner = address(this);
        vm.startPrank(owner);
        bool ok;
        try c.updateRoundImplementation(payable(newRoundImplementation)) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // Rule: a successful update by the owner must always leave a NONZERO
        // roundImplementation; the reference guarantees this (it rejects the
        // zero address), the mutant stores address(0) and violates it.
        assertTrue(!(ok && c.roundImplementation() == address(0)));
    }
}
